    id uuid NOT NULL,
    "dataPoints" json NOT NULL,
    status character varying(64) DEFAULT 'pending'::character varying NOT NULL,
    "deliveredAt" timestamp(3) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    "lastAttemptAt" timestamp(3) with time zone,
    "lastError" text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    "updatedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT "CHK_instance_monitoring_report_status" CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'delivered'::character varying, 'skipped_after_max_retries'::character varying])::text[])))
);


