--

COMMENT ON COLUMN public.instance_monitoring_report."lastAttemptAt" IS 'When the last attempt finished; NULL before the first. Paces retries across a restart.';


--
-- Name: COLUMN instance_monitoring_report."lastError"; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.instance_monitoring_report."lastError" IS 'Message of the most recent delivery failure.';


