.first().json;\\nreturn [{\\n  json: {\\n    email: data.sender_email || data.email || 'customer@example.com',\\n    full_name: data.extracted_name,\\n    phone: data.extracted_phone,\\n    company: data.extracted_company,\\n    budget: Number(data.extracted_budget),\\n    requirement: data.extracted_requirement\\n  }\\n}];","notice":""},"id":"3b712e36-eb87-4868-bdd2-7b84937d96bb","name":"JSON Lead Formatter Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-656,128]},{"parameters":{"resource":"database","operation":"executeQuery","query":"SELECT * FROM crm_customers WHERE email = '{{ $json.email }}';","options":{}},"id":"3ffc4661-ae87-4538-b51c-1a5757fd83b3","name":"Check Customer Exists Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[-448,128],"alwaysOutputData":true,"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"id":"c1","leftValue":"=={{ $json.id }}\\n","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"id":"1268caab-4230-416c-b18c-faaaad27f825","name":"IF Existing Customer","type":"n8n-nodes-base.if","typeVersion":2,"position":[-224,128]},{"parameters":{"resource":"database","operation":"executeQuery","query":"INSERT INTO crm_customers (email, full_name, company, phone, status) VALUES ('{{ $('JSON Lead Formatter Code').item.json.email }}', '{{ $('JSON Lead Formatter Code').item.json.full_name }}', '{{ $('JSON Lead Formatter Code').item.json.company }}', '{{ $('JSON Lead Formatter Code').item.json.phone }}', 'NEW') RETURNING *;","options":{}},"id":"164d5247-1456-475c-b0ca-57746efdc9cb","name":"Insert Customer Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[0,240],"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"resource":