38	{"id":"JmuBZNxuqJaOUbpK","name":"Luồng 5: AI Email-to-CRM Lead Extraction & Follow-up","nodes":[{"parameters":{"multipleMethods":false,"httpMethod":"POST","path":"crm-lead-intake","authentication":"none","responseMode":"onReceived","responseCode":200,"contentTypeNotice":"","options":{}},"id":"c787e74a-2973-43a4-9dd3-0cb5cda8bb13","name":"Webhook Sales Trigger","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[-1328,128],"webhookId":"d965ee77-fa7b-490b-92cf-0c5beee48c7f"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const body = $input.first().json.body || $input.first().json;\\nconst content = body.content || body.text || '';\\nconst parts = content.split(/Trân trọng|Best regards|Thanks|Kính thư/i);\\nreturn [{\\n  json: {\\n    ...body,\\n    clean_body: parts[0] ? parts[0].trim() : content,\\n    signature: parts[1] ? parts[1].trim() : ''\\n  }\\n}];","notice":""},"id":"06192d62-133d-4f4e-a862-a44cdf769252","name":"Extract Signature Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1104,128]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const item = $input.first().json;\\nconst text = (item.clean_body + ' ' + item.signature);\\nconst phoneMatch = text.match(/(\\\\+84|0)\\\\d{9,10}/);\\nconst budgetMatch = text.match(/(\\\\d+)\\\\s*(tr|triệu|million|k)/i);\\n\\nreturn [{\\n  json: {\\n    ...item,\\n    extracted_name: item.sender_name || 'Khách hàng',\\n    extracted_phone: phoneMatch ? phoneMatch[0] : '0901234567',\\n    extracted_company: item.company || 'Doanh nghiệp đối tác',\\n    extracted_budget: budgetMatch ? 60000000 : 20000000,\\n    extracted_requirement: item.subject || 'Quan tâm giải pháp phần mềm'\\n  }\\n}];","notice":""},"id":"1676e938-9880-4e93-9c77-d9ad14b1626f","name":"AI Entity Extractor Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-880,128]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const data = $input.first().json;\\nreturn [{\\n  json: {\\n    email: data.sender_email || data.email || 'customer@example.com',\\n    full_name: data.extracted_name,\\n    phone: data.extracted_phone,\\n    company: data.extracted_company,\\n    budget: Number(data.extracted_budget),\\n    requirement: data.extracted_requirement\\n  }\\n}];","notice":""},"id":"3b712e36-eb87-4868-bdd2-7b84937d96bb","name":"JSON Lead Formatter Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-656,128]},{"parameters":{"resource":"database","operation":"executeQuery","query":"SELECT * FROM crm_customers WHERE email = '{{ $json.email }}';","options":{}},"id":"3ffc4661-ae87-4538-b51c-1a5757fd83b3","name":"Check Customer Exists Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[-448,128],"alwaysOutputData":true,"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"id":"c1","leftValue":"=={{ $json.id }}\\n","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"id":"1268caab-4230-416c-b18c-faaaad27f825","name":"IF Existing Customer","type":"n8n-nodes-base.if","typeVersion":2,"position":[-224,128]},{"parameters":{"resource":"database","operation":"executeQuery","query":"INSERT INTO crm_customers (email, full_name, company, phone, status) VALUES ('{{ $('JSON Lead Formatter Code').item.json.email }}', '{{ $('JSON Lead Formatter Code').item.json.full_name }}', '{{ $('JSON Lead Formatter Code').item.json.company }}', '{{ $('JSON Lead Formatter Code').item.json.phone }}', 'NEW') RETURNING *;","options":{}},"id":"164d5247-1456-475c-b0ca-57746efdc9cb","name":"Insert Customer Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[0,240],"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"resource":