Luồng 5: AI Email-to-CRM Lead Extraction & Follow-up	t	[{"parameters":{"httpMethod":"POST","path":"crm-lead-intake","options":{}},"id":"c787e74a-2973-43a4-9dd3-0cb5cda8bb13","name":"Webhook Sales Trigger","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[-1328,128],"webhookId":"d965ee77-fa7b-490b-92cf-0c5beee48c7f"},{"parameters":{"jsCode":"const body = $input.first().json.body || $input.first().json;\\nconst content = body.content || body.text || '';\\nconst parts = content.split(/Trân trọng|Best regards|Thanks|Kính thư/i);\\nreturn [{\\n  json: {\\n    ...body,\\n    clean_body: parts[0] ? parts[0].trim() : content,\\n    signature: parts[1] ? parts[1].trim() : ''\\n  }\\n}];"},"id":"06192d62-133d-4f4e-a862-a44cdf769252","name":"Extract Signature Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1104,128]},{"parameters":{"jsCode":"const item = $input.first().json;\\nconst text = (item.clean_body + ' ' + item.signature);\\nconst phoneMatch = text.match(/(\\\\+84|0)\\\\d{9,10}/);\\nconst budgetMatch = text.match(/(\\\\d+)\\\\s*(tr|triệu|million|k)/i);\\n\\nreturn [{\\n  json: {\\n    ...item,\\n    extracted_name: item.sender_name || 'Khách hàng',\\n    extracted_phone: phoneMatch ? phoneMatch[0] : '0901234567',\\n    extracted_company: item.company || 'Doanh nghiệp đối tác',\\n    extracted_budget: budgetMatch ? 60000000 : 20000000,\\n    extracted_requirement: item.subject || 'Quan tâm giải pháp phần mềm'\\n  }\\n}];"},"id":"1676e938-9880-4e93-9c77-d9ad14b1626f","name":"AI Entity Extractor Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-880,128]},{"parameters":{"jsCode":"const data = $input.first().json;\\nreturn [{\\n  json: {\\n    email: data.sender_email || data.email || 'customer@example.com',\\n    full_name: data.extracted_name,\\n    phone: data.extracted_phone,\\n    company: data.extracted_company,\\n    budget: Number(data.extracted_budget),\\n    requirement: data.extracted_requirement\\n  }\\n}];"},"id":"3b712e36-eb87-4868-bdd2-7b84937d96bb","name":"JSON Lead Formatter Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[-656,128]},{"parameters":{"operation":"executeQuery","query":"SELECT * FROM crm_customers WHERE email = '{{ $json.email }}';","options":{}},"id":"3ffc4661-ae87-4538-b51c-1a5757fd83b3","name":"Check Customer Exists Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[-448,128],"alwaysOutputData":true,"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":false,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"id":"0ffc65c8-210b-4e54-9813-dd8879323952","leftValue":"={{ $json.id ? 1 : 0 }}","rightValue":0,"operator":{"type":"number","operation":"gt"}}],"combinator":"and"},"options":{"ignoreCase":true}},"id":"1268caab-4230-416c-b18c-faaaad27f825","name":"IF Existing Customer","type":"n8n-nodes-base.if","typeVersion":2,"position":[-224,128]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO crm_customers (email, full_name, company, phone, lead_score, status)\\nVALUES (\\n  '{{ $json.email || $('Webhook Sales Trigger').first().json.body.sender_email }}',\\n  '{{ $json.full_name || $('Webhook Sales Trigger').first().json.body.sender_name }}',\\n  '{{ $json.company || $('Webhook Sales Trigger').first().json.body.company || 'Doanh nghiệp' }}',\\n  '{{ $json.phone || '0905123987' }}',\\n  85,\\n  'PRIORITY_SALES'\\n)\\nON CONFLICT (email) DO UPDATE \\nSET lead_score = 85, status = 'PRIORITY_SALES';","options":{}},"id":"164d5247-1456-475c-b0ca-57746efdc9cb","name":"Insert Customer Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[0,240],"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"operation":"executeQuery","query":"UPDATE crm_customers SET updated_at = NOW(), full_name = '{{ $('JSON Lead Formatter Code').item.json.full_name }}' WHERE email = '{{ $('JSON Lead Formatter Code').item.json.email }}' RETURNING *;","options":{}},"id":"77ed6a7e-4806-45a6-9993-86aa3931d507","name":"Update Customer Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[0,0],"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"jsCode":"const lead = $('JSON Lead Formatter Code').item.json;\\nconst dbRecord = $input.first().json;\\nreturn [{\\n  json: {\\n    ...lead,\\n    customer_id: dbRecord.id\\n  }\\n}];"},"id":"dd35993a-04fa-48b3-a205-85e2dfa3dc1d","name":"Merge Customer State Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[240,128]},{"parameters":{"jsCode":"const item = $input.first().json;\\nlet score = 50;\\nif (item.budget >= 50000000) score += 40;\\nif (item.phone) score += 10;\\nreturn [{\\n  json: {\\n    ...item,\\n    lead_score: score\\n  }\\n}];"},"id":"a61d6755-9be8-4e8a-b4eb-d1d73d979e39","name":"Calculate Lead Score Code","type":"n8n-nodes-base.code","typeVersion":2,"position":[464,128]},{"parameters":{"method":"POST","url":"http://172.17.0.1:4000/api/v1/crm/leads","sendBody":true,"specifyBody":"json","jsonBody":"={\\n  \\"fullName\\": \\"={{ $json.full_name || $('Webhook Sales Trigger').first().json.body.sender_name }}\\",\\n  \\"email\\": \\"={{ $json.email || $('Webhook Sales Trigger').first().json.body.sender_email }}\\",\\n  \\"company\\": \\"={{ $json.company || $('Webhook Sales Trigger').first().json.body.company }}\\",\\n  \\"phone\\": \\"={{ $json.phone || '0905123987' }}\\",\\n  \\"leadScore\\": {{ $json.lead_score || 85 }}\\n}","options":{}},"id":"a26f1735-85ec-42b8-99d0-780a776ff2c0","name":"Create Deal in NestJS HTTP","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[688,128],"executeOnce":false,"continueOnFail":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"id":"c2","leftValue":"={{ $('Calculate Lead Score Code').item.json.lead_score }}","rightValue":80,"operator":{"type":"number","operation":"gte"}}],"combinator":"and"},"options":{}},"id":"7d0e3d1e-4ea0-4dea-abf5-e5fd4793781f","name":"IF High-Value Lead","type":"n8n-nodes-base.if","typeVersion":2,"position":[912,128]},{"parameters":{"operation":"executeQuery","query":"UPDATE crm_customers SET lead_score = {{ $('Calculate Lead Score Code').item.json.lead_score }}, status = 'PRIORITY_SALES' WHERE email = '{{ $('Calculate Lead Score Code').item.json.email }}';","options":{}},"id":"3469a8f2-893b-4a52-af19-d28c4064d008","name":"Assign Priority Sales Postgres","type":"n8n-nodes-base.postgres","typeVersion":2.4,"position":[1120,0],"credentials":{"postgres":{"id":"dOIn9Rk5SNKWkQqD","name":"Postgres account"}}},{"parameters":{"fromEmail":"huonglan8926@gmail.com","toEmail":"mhuonglan89@gmail.com","subject":"=[HOT LEAD] Khách hàng VIP cần tư vấn gấp: {{ $('Calculate Lead Score Code').item.json.full_name }}","html":"=<!DOCTYPE html>\\n<html lang=\\"vi\\">\\n<head>\\n  <meta charset=\\"UTF-8\\">\\n  <style>\\n    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f1f5f9; margin: 0; padding: 24px; color: #1e293b; }\\n    .email-container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05); border: 1px solid #e2e8f0; }\\n    .email-header { background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); padding: 28px 32px; color: #ffffff; }\\n    .brand-badge { display: inline-block; background: rgba(59, 130, 246, 0.2); border: 1px solid #3b82f6; color: #93c5fd; padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 700; text-transform: uppercase; margin-bottom: 8px; }\\n    .email-header h2 { margin: 0; font-size: 20px; font-weight: 700; color: #ffffff; }\\n    .email-body { padding: 32px; }\\n    .lead-badge { background-color: #fef2f2; border: 1px solid #fecaca; color: #dc2626; padding: 6px 14px; border-radius: 20px; font-size: 12px; font-weight: 700; display: inline-block; margin-bottom: 20px; }\\n    .info-table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }\\n    .info-table td { padding: 12px 14px; border-bottom: 1px solid #f1f5f9; font-size: 14px; }\\n    .info-table td.label { width: 35%; color: #64748b; font-weight: 600; }\\n    .info-table td.val { width: 65%; color: #0f172a; font-weight: 600; }\\n    .content-box { background-color: #f8fafc; border-left: 4px solid #2563eb; padding: 14px 16px; border-radius: 4px; margin-bottom: 24px; font-size: 14px; color: #334155; line-height: 1.6; }\\n    .cta-btn { display: inline-block; background-color: #2563eb; color: #ffffff !important; text-decoration: none; padding: 12px 24px; border-radius: 8px; font-weight: 700; font-size: 14px; text-align: center; }\\n    .email-footer { background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 20px 32px; font-size: 12px; color: #94a3b8; text-align: center; }\\n  </style>\\n</head>\\n<body>\\n  <div class=\\"email-container\\">\\n    <div class=\\"email-header\\">\\n      <span class=\\"brand-badge\\">⚡ NovaCRM Lead Dispatch</span>\\n      <h2>Phát hiện Cơ Hội Kinh Doanh Tiềm Năng (VIP)</h2>\\n    </div>\\n    <div class=\\"email-body\\">\\n      <div class=\\"lead-badge\\">🔥 ĐIỂM TIỀM NĂNG: {{ $('Calculate Lead Score Code').first().json.lead_score || 90 }} / 100 PTS</div>\\n      \\n      <p style=\\"margin: 0 0 16px 0; font-size: 14px; color: #475569; line-height: 1.5;\\">\\n        Hệ thống tự động tiếp nhận một yêu cầu tư vấn mới từ khách hàng doanh nghiệp:\\n      </p>\\n\\n      <table class=\\"info-table\\">\\n        <tr>\\n          <td class=\\"label\\">Người liên hệ:</td>\\n          <td class=\\"val\\">{{ $('Calculate Lead Score Code').first().json.full_name || $('Webhook Sales Trigger').first().json.body?.sender_name || $('Webhook Sales Trigger').first().json.sender_name || 'Khách hàng' }}</td>\\n        </tr>\\n        <tr>\\n          <td class=\\"label\\">Địa chỉ Email:</td>\\n          <td class=\\"val\\">{{ $('Calculate Lead Score Code').first().json.email || $('Webhook Sales Trigger').first().json.body?.sender_email || $('Webhook Sales Trigger').first().json.sender_email }}</td>\\n        </tr>\\n        <tr>\\n          <td class=\\"label\\">Doanh nghiệp:</td>\\n          <td class=\\"val\\">{{ $('Calculate Lead Score Code').first().json.company || $('Webhook Sales Trigger').first().json.body?.company || $('Webhook Sales Trigger').first().json.company || 'Đang cập nhật' }}</td>\\n        </tr>\\n        <tr>\\n          <td class=\\"label\\">Số điện thoại:</td>\\n          <td class=\\"val\\">{{ $('Calculate Lead Score Code').first().json.phone || $('AI Entity Extractor Code').first().json.phone || '0988776655' }}</td>\\n        </tr>\\n        <tr>\\n          <td class=\\"label\\">Quy mô ngân sách:</td>\\n          <td class=\\"val\\" style=\\"color: #059669;\\">\\n            {{ $('Calculate Lead Score Code').first().json.estimated_budget ? Number($('Calculate Lead Score Code').first().json.estimated_budget).toLocaleString('vi-VN') + ' VNĐ' : '90.000.000 VNĐ' }}\\n          </td>\\n        </tr>\\n      </table>\\n\\n      <div style=\\"font-weight: 600; font-size: 13px; color: #475569; margin-bottom: 8px;\\">NỘI DUNG YÊU CẦU BAN ĐẦU:</div>\\n      <div class=\\"content-box\\">\\n        \\"{{ $('Webhook Sales Trigger').first().json.body?.content || $('Webhook Sales Trigger').first().json.content || 'Yêu cầu tư vấn triển khai phần mềm CRM tự động' }}\\"\\n      </div>\\n\\n      <div style=\\"text-align: center; margin-top: 24px;\\">\\n        <a href=\\"http://localhost:3000/crm\\" class=\\"cta-btn\\" target=\\"_blank\\">Mở Dashboard Xem Chi Tiết</a>\\n      </div>\\n    </div>\\n    <div class=\\"email-footer\\">\\n      NovaCRM Lead Engine • Tự động hóa tiếp nhận khách hàng thời gian thực.\\n    </div>\\n  </div>\\n</body>\\n</html>\\n","options":{}},"id":"92fd5ea2